Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'
$ProgressPreference = 'SilentlyContinue'

try { [Console]::OutputEncoding = New-Object System.Text.UTF8Encoding $false } catch { }

function Write-Step { param([string]$Text) Write-Host "`n>> $Text" -ForegroundColor Cyan }
function Write-Ok   { param([string]$Text) Write-Host "   [ok] $Text" -ForegroundColor Green }
function Write-Bad  { param([string]$Text) Write-Host "   [!] $Text"  -ForegroundColor Red }
function Write-Note { param([string]$Text) Write-Host "   $Text"      -ForegroundColor DarkGray }

function Read-Required {
    param([string]$Prompt)
    do {
        $value = (Read-Host "   $Prompt").Trim()
        if (-not $value) { Write-Bad 'Pusto. Spróbuj jeszcze raz.' }
    } while (-not $value)
    return $value
}

function Read-Email {
    param([string]$Prompt)
    do {
        $value = (Read-Host "   $Prompt").Trim()
        if ($value -notmatch '^[^@\s]+@[^@\s]+\.[^@\s]+$') {
            Write-Bad 'To nie wygląda na adres e-mail. Spróbuj jeszcze raz.'
            $value = ''
        }
    } while (-not $value)
    return $value
}

function Update-Path {
    $machine = [Environment]::GetEnvironmentVariable('Path', 'Machine')
    $user    = [Environment]::GetEnvironmentVariable('Path', 'User')
    $env:Path = @($machine, $user | Where-Object { $_ }) -join ';'
}

function Add-ToUserPath {
    param([string]$Dir)

    $key = 'HKCU:\Environment'
    $raw = (Get-Item $key).GetValue('Path', '', 'DoNotExpandEnvironmentNames')
    $parts = @($raw -split ';' | Where-Object { $_ })

    if ($parts -notcontains $Dir) {
        Set-ItemProperty -Path $key -Name Path -Value ((@($parts) + $Dir) -join ';') -Type ExpandString
    }
    if (($env:Path -split ';') -notcontains $Dir) { $env:Path = "$env:Path;$Dir" }
}

function Set-Wallpaper {
    param([string]$Path)

    if (-not ('Rcng.Native' -as [type])) {
        Add-Type -Namespace Rcng -Name Native -MemberDefinition @'
[DllImport("user32.dll", CharSet = CharSet.Unicode, SetLastError = true)]
public static extern bool SystemParametersInfo(uint action, uint param, string value, uint flags);
'@
    }

    $key = 'HKCU:\Control Panel\Desktop'
    Set-ItemProperty -Path $key -Name WallpaperStyle -Value '10'
    Set-ItemProperty -Path $key -Name TileWallpaper  -Value '0'

    [void][Rcng.Native]::SystemParametersInfo(20, 0, $Path, 3)
}

function Restart-Explorer {
    Stop-Process -Name explorer -Force -ErrorAction SilentlyContinue
    Start-Sleep -Seconds 2
    if (-not (Get-Process -Name explorer -ErrorAction SilentlyContinue)) {
        Start-Process explorer.exe
        Start-Sleep -Seconds 2
    }
}

function Install-NodeForUser {
    param([string]$TargetDir)

    $index = Invoke-RestMethod -Uri 'https://nodejs.org/dist/index.json'
    $release = $index | Where-Object { $_.lts } | Select-Object -First 1
    $version = $release.version

    if ($version -notmatch '^v\d+\.\d+\.\d+$') {
        throw "Nie udało się ustalić wersji LTS Node.js."
    }

    $arch = if ($env:PROCESSOR_ARCHITECTURE -eq 'ARM64') { 'arm64' } else { 'x64' }
    $name = "node-$version-win-$arch"

    Write-Note "Ściągam $name.zip - około 30 MB, chwilę to zejdzie."
    $zip = Join-Path $env:TEMP "$name.zip"
    Invoke-WebRequest -Uri "https://nodejs.org/dist/$version/$name.zip" -OutFile $zip -UseBasicParsing

    $sums = (Invoke-WebRequest -Uri "https://nodejs.org/dist/$version/SHASUMS256.txt" -UseBasicParsing).Content
    $entry = ($sums -split "`n") | Where-Object { $_ -match ([regex]::Escape("$name.zip") + '\s*$') } | Select-Object -First 1
    $want = ($entry -split '\s+')[0]
    $have = (Get-FileHash -Path $zip -Algorithm SHA256).Hash.ToLower()

    if ($want.Length -ne 64 -or $want -ne $have) {
        Remove-Item $zip -Force
        throw "Suma kontrolna archiwum Node.js się nie zgadza."
    }

    $unpack = Join-Path $env:TEMP 'rcng-node-unpack'
    if (Test-Path $unpack)    { Remove-Item $unpack -Recurse -Force }
    if (Test-Path $TargetDir) { Remove-Item $TargetDir -Recurse -Force }

    Expand-Archive -Path $zip -DestinationPath $unpack -Force
    Move-Item -Path (Join-Path $unpack $name) -Destination $TargetDir
    Remove-Item $zip -Force
    Remove-Item $unpack -Recurse -Force

    return $version
}

function Test-Tool {
    param([string]$Label, [string]$Exe, [string]$ExpectedVersion = '')
    try {
        $LASTEXITCODE = 0
        $out = & $Exe --version
        $exitCode = $LASTEXITCODE
        $firstLine = [string]($out | Select-Object -First 1)
        if ($exitCode -eq 0 -and $firstLine -match '^(?:git version |v)?\d+\.\d+\.\d+' -and
            (-not $ExpectedVersion -or $firstLine.Trim() -eq $ExpectedVersion)) {
            Write-Ok "$Label $firstLine"
            return $true
        }
    }
    catch { }
    Write-Bad "$Label – nie odpowiada"
    return $false
}

function Invoke-RcngInstaller {

    Write-Host ''
    Write-Host '  RCNG Installer' -ForegroundColor White
    Write-Host '  --------------' -ForegroundColor DarkGray

    if (-not (Get-Command winget -ErrorAction SilentlyContinue)) {
        Write-Bad 'Nie ma winget. Zaktualizuj "Instalator aplikacji" w Microsoft Store i wróć tutaj.'
        return
    }

    $rcngDir = Join-Path $env:LOCALAPPDATA 'rcng'
    New-Item -ItemType Directory -Force -Path $rcngDir | Out-Null

    Write-Step 'Ustawiam tapetę'
    $catPath = Join-Path $rcngDir 'cat.jpg'
    [IO.File]::WriteAllBytes($catPath, [Convert]::FromBase64String($script:CatJpgBase64))
    Set-Wallpaper -Path $catPath
    Write-Ok 'Kot na miejscu.'

    Write-Step 'Otwieram rejestrację na GitHubie'
    Start-Process 'https://github.com/signup'
    Write-Ok 'Załóż konto, zaraz o nie zapytam.'

    Write-Step 'Instaluję Git i VS Code'
    $packages = @(
        'Git.Git'
        'Microsoft.VisualStudioCode'
    )
    foreach ($id in $packages) {
        Write-Note "→ $id"
        $window = Start-Process -FilePath 'cmd.exe' -Wait -PassThru -ArgumentList '/d', '/c', (
            "winget install --id $id -e --source winget --scope user " +
            '--accept-source-agreements --accept-package-agreements'
        )
        # 0x8A15002B: brak nowszej wersji. Nadal wymagamy sprawdzenia narzędzia poniżej.
        if ($window.ExitCode -eq -1978335189) {
            Write-Note "$id jest już aktualny; sprawdzę pliki i wersję."
        }
        elseif ($window.ExitCode -ne 0) {
            throw "Instalacja $id dla użytkownika nie powiodła się (kod $($window.ExitCode))."
        }
    }

    Write-Step 'Instaluję Node.js'
    $nodeDir = Join-Path $rcngDir 'node'
    try {
        $nodeVersion = Install-NodeForUser -TargetDir $nodeDir
        Add-ToUserPath -Dir $nodeDir
        Write-Ok "Node.js $nodeVersion rozpakowany, PATH dopisany."
    }
    catch {
        Write-Bad "Node.js nie wszedł: $($_.Exception.Message)"
        return
    }

    Write-Step 'Sprawdzam, co się zainstalowało'
    Update-Path
    $gitExe = Join-Path $env:LOCALAPPDATA 'Programs\Git\cmd\git.exe'
    $codeCmd = Join-Path $env:LOCALAPPDATA 'Programs\Microsoft VS Code\bin\code.cmd'
    $results = @(
        Test-Tool -Label 'git ' -Exe $gitExe
        Test-Tool -Label 'code' -Exe $codeCmd
        Test-Tool -Label 'node' -Exe (Join-Path $nodeDir 'node.exe') -ExpectedVersion $nodeVersion
        Test-Tool -Label 'npm ' -Exe (Join-Path $nodeDir 'npm.cmd')
    )
    if ($results -contains $false) {
        Write-Host ''
        throw 'Nie wszystkie narzędzia działają w katalogach użytkownika. Sprawdź błędy powyżej.'
    }

    Write-Step 'Podaj dane z nowego konta'
    $userName  = Read-Required 'Nazwa użytkownika z GitHuba (user.name)'
    $userEmail = Read-Email    'Adres e-mail z GitHuba (user.email)'

    & $gitExe config --global user.name $userName
    if ($LASTEXITCODE -ne 0) {
        throw "Nie udało się zapisać git user.name (kod $LASTEXITCODE)."
    }
    & $gitExe config --global user.email $userEmail
    if ($LASTEXITCODE -ne 0) {
        throw "Nie udało się zapisać git user.email (kod $LASTEXITCODE)."
    }
    Write-Ok 'Git wie już, kim jesteś.'

    $desktop = [Environment]::GetFolderPath('Desktop')
    $batPath = Join-Path $desktop 'logout.bat'
    [IO.File]::WriteAllText(
        $batPath,
        "@echo off`r`ngit credential-manager github logout $userName`r`npause`r`n",
        [Text.Encoding]::Default
    )
    Write-Ok 'logout.bat czeka na pulpicie.'

    Set-Clipboard -Value "$userName <$userEmail>"
    Write-Ok 'Nazwa i e-mail skopiowane do schowka.'

    Write-Step 'Odświeżam pulpit'
    Write-Note 'Restartuję explorera, otwarte okna eksploratora się zamkną.'
    Restart-Explorer
    Write-Ok 'PATH gotowy w nowych oknach.'

    Write-Host ''
    Write-Host '  Gotowe.' -ForegroundColor Green
    Write-Host ''
    Write-Host '  Zostało jedno: wyślij mi zawartość schowka na Teamsie.' -ForegroundColor Yellow
    Write-Host ''
}

